<template><section class="dm-admin-reports"><header><h3>私信举报</h3><PButton size="sm" variant="secondary" :loading="loading" @click="load">刷新</PButton></header><p v-if="error" role="alert">{{ error }}</p><p v-else-if="!reports.length && !loading">暂无举报</p><article v-for="report in reports" :key="report.id"><div><strong>{{ report.reason }}</strong><span>{{ report.status }}</span></div><p>{{ report.snapshot_content || (report.has_snapshot_image ? '含图片' : '无文字内容') }}</p><small>{{ report.conversation_context }} · {{ formatTime(report.created_at) }}</small><div v-if="report.status === 'pending'"><PButton size="sm" @click="update(report.id, 'resolved')">处理完成</PButton><PButton size="sm" variant="secondary" @click="update(report.id, 'dismissed')">驳回</PButton></div></article><PButton v-if="cursor" variant="secondary" @click="loadMore">加载更多</PButton></section></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import PButton from '@/components/ui/PButton.vue'; import { listDMReports, updateDMReport, type DMReport } from '@/api/dm'; const reports=ref<DMReport[]>([]);const cursor=ref<string>();const loading=ref(false);const error=ref('');const fetchPage=async(append=false)=>{loading.value=true;error.value='';try{const page=await listDMReports(append?cursor.value:undefined);reports.value=append?[...reports.value,...page.items]:page.items;cursor.value=page.next_cursor}catch{error.value='加载失败'}finally{loading.value=false}};const load=()=>fetchPage();const loadMore=()=>fetchPage(true);const update=async(id:string,status:'resolved'|'dismissed')=>{try{const next=await updateDMReport(id,status);reports.value=reports.value.map(report=>report.id===id?next:report)}catch{error.value='操作失败'}};const formatTime=(value:string)=>new Date(value).toLocaleString('zh-CN');onMounted(load)
</script>
<style scoped>.dm-admin-reports{display:grid;gap:.75rem}.dm-admin-reports header,.dm-admin-reports article>div{display:flex;justify-content:space-between;align-items:center;gap:.5rem}.dm-admin-reports h3,.dm-admin-reports p{margin:0}.dm-admin-reports article{display:grid;gap:.5rem;padding:1rem 0;border-top:1px solid var(--a-color-border-soft)}.dm-admin-reports small{color:var(--a-color-muted)}.dm-admin-reports article>div:last-child{justify-content:flex-start}</style>
